update public.places set address = '강원특별자치도 속초시 선사로1길 16', latitude = 38.188245, longitude = 128.590783, summary = '청동기 시대 집터와 고인돌이 나온 국가 사적', tags = array['free'], description = '청초호 서쪽 언덕에서 1992년 발굴된 신석기 말~청동기 초의 유적으로, 움집터 7기와 고인돌 2기가 확인되어 국가 사적으로 지정되었습니다. 고인돌에서는 남한에서 처음으로 부채꼴 청동도끼가 나왔습니다. 건물 없이 야외에 유적만 있어 언제든 볼 수 있고, 20~30분이면 둘러볼 수 있습니다.', hours_summary = null, closed_summary = null, price_summary = '무료', phone = '033-639-2958', parking_summary = '무료', cautions = null, operation_status = 'open', status_note = null, verified_on = '2026-11-21'
