update public.places set address = '강원특별자치도 속초시 조양동 일대', latitude = 38.178306, longitude = 128.572196, summary = '정상까지 30~40분, 속초 시내와 설악산이 보이는 낮은 산', tags = array['free'], description = '조양동에 있는 해발 230m 남짓의 낮은 산으로, 속초 8경 중 하나입니다. 어느 들머리에서 올라도 정상까지 30~40분이면 닿고, 길목에 운동시설과 쉼터, 전망대가 있습니다. 정상에서는 속초 시가지와 동해, 울산바위와 달마봉 같은 설악산 능선이 보여 가벼운 산행이나 해돋이 산책으로 찾기 좋습니다.', hours_summary = null, closed_summary = null, price_summary = '무료', phone = null, parking_summary = null, cautions = '해돋이를 보러 오를 때는 어두운 산길이라 손전등을 챙기세요.', operation_status = 'open', status_note = null, verified_on = '2026-11-21'
where slug = 'cheongdaesan' and activity_category = 'nature' and description is null;
update public.places set address = '강원특별자치도 속초시 엑스포로 140', latitude = 38.196060, longitude = 128.582464, summary = '청초호 산책로와 엑스포타워가 있는 도심 공원', tags = array['free', 'kids'], description = '속초 시내 한가운데 청초호 호숫가에 꾸민 공원으로, 산책로와 벤치, 밤에 불을 밝히는 조형물이 있고 호수 위 정자 청초정에서 설악산과 바다 쪽을 볼 수 있습니다. 공원 옆 73.4m 높이의 엑스포타워 전망대에 오르면 동해와 설악산, 시내가 한눈에 보입니다. 평탄한 길이라 아이와 함께 1시간 안팎으로 걷기 좋고, 야경을 보러 저녁에 찾아도 좋습니다.', hours_summary = null, closed_summary = null, price_summary = '무료(엑스포타워 전망대 어른 2,500원 · 청소년 2,000원 · 어린이 1,500원)', phone = null, parking_summary = '무료', cautions = '엑스포타워 전망대는 09:00~22:00 운영하고 21:30에 입장을 마감합니다.', operation_status = 'open', status_note = null, verified_on = '2026-11-21'
where slug = 'cheongcho-lake-park' and activity_category = 'nature' and description is null;
update public.places set address = '강원특별자치도 속초시 청호로 120-1', latitude = 38.200226, longitude = 128.595745, summary = '아바이마을 끝, 파도가 잔잔한 작은 해변', tags = array['free', 'kids'], description = '아바이마을 끝자락의 작은 해변으로, 방파제가 바다를 감싸 파도가 잔잔하고 물이 얕아 어린아이와 물놀이하기 좋습니다. 등대가 선 방파제 옆이라 다른 해변보다 한적하고, 아바이마을 구경이나 순대 식사와 묶어 들르기에 맞습니다.', hours_summary = '물놀이는 여름 개장 기간(7월 초~8월 하순)에만 가능', closed_summary = null, price_summary = '무료', phone = null, parking_summary = null, cautions = '개장 기간이 아니면 안전요원이 없어 물에 들어가지 마세요.', operation_status = 'open', status_note = null, verified_on = '2026-11-21'
where slug = 'cheongho-beach' and activity_category = 'nature' and description is null;
update public.places set address = '강원특별자치도 속초시 설악동 설악산국립공원', latitude = 38.162037, longitude = 128.498735, summary = '비룡폭포 위에서 320m 토왕성폭포를 바라보는 전망대', tags = array['free'], description = '상·중·하 3단을 합쳐 약 320m에 이르는 토왕성폭포를 멀리서 바라보는 전망대로, 비룡폭포 탐방로를 약 400m 늘려 만들었습니다. 소공원에서 육담폭포·비룡폭포를 지나 약 2.8km, 편도 1시간 30분 안팎이 걸리며, 비룡폭포부터 전망대까지는 계단이 많아 가장 힘든 구간입니다. 겨울에는 폭포가 얼어 큰 빙폭이 되고, 날씨가 흐리면 폭포가 잘 보이지 않을 수 있습니다.', hours_summary = '입산 가능 시간 동절기 04:00~12:00 · 하절기 03:00~14:00', closed_summary = null, price_summary = '무료', phone = '033-801-0900', parking_summary = '설악산 소공원 유료 주차장 이용', cautions = '비룡폭포에서 전망대까지 약 400m가 계단 위주의 오르막입니다.
주변에 낙석·낙빙 위험이 있어 정해진 길로만 다니세요.', operation_status = 'open', status_note = null, verified_on = '2026-11-21'
where slug = 'towangseong-falls-observatory' and activity_category = 'nature' and description is null;
update public.places set address = '강원특별자치도 속초시 설악동 설악산국립공원', latitude = 38.189891, longitude = 128.474955, summary = '계조암 앞 너른 바위 위에 얹힌 흔들리는 둥근 바위', tags = array['free'], description = '신흥사에 딸린 암자 계조암 앞의 넓은 반석 위에 얹힌 둥근 바위로, 혼자 밀어도 여럿이 밀어도 비슷하게 흔들린다고 알려져 있습니다. 소공원에서 신흥사를 지나 울산바위로 오르는 길 중간에 있어 편도 1시간 정도면 닿고, 여기서 울산바위까지는 1시간 남짓 더 걸립니다. 바로 뒤 큰 바위 속에 계조암 법당이 있어 함께 둘러볼 수 있습니다.', hours_summary = null, closed_summary = null, price_summary = '무료', phone = '033-801-0900', parking_summary = '설악산 소공원 유료 주차장 이용', cautions = null, operation_status = 'open', status_note = null, verified_on = '2026-11-21'
